  if (body instanceof FormData) {
    opts.headers = { Authorization: AUTH };
    opts.body = body;
  } else {
    opts.headers = hdrs;
    if (body !== undefined) opts.body = JSON.stringify(body);
  }
  const res = await fetch(url, opts);
